export function ResetButton({
  label = "{{label}}",
  variant = "{{variant}}",
  bg = "{{bg}}",
  radius = {{radius}},
  disabled = {{disabled}},
}) {
  const ghost = variant === "ghost";
  return (
    <form style={{ display: "inline-block" }}>
      <button
        type="reset"
        disabled={disabled}
        style={{
          padding: "11px 20px",
          borderRadius: radius,
          border: `2px solid ${ghost ? "transparent" : bg}`,
          background: "transparent",
          color: bg,
          font: "600 15px/1 system-ui, sans-serif",
          cursor: disabled ? "not-allowed" : "pointer",
          opacity: disabled ? 0.45 : 1,
        }}
      >
        {label}
      </button>
    </form>
  );
}
